import React, { useMemo, useState } from 'react';
import './index.css';

const initialReports = [
  { id:'CEGCT-2025-0042', category:'Illegal dumping', severity:'CRITICAL', status:'SUBMITTED', location:'Area 18, Lilongwe', date:'Today, 09:42', reporter:'Grace Banda', officer:'Unassigned', description:'Large pile of construction waste dumped beside the stream. Runoff is entering the waterway.', lat:'-13.925', lon:'33.781', image:'https://images.unsplash.com/photo-1605600659873-d808a13e4d9a?auto=format&fit=crop&w=900&q=80' },
  { id:'CEGCT-2025-0041', category:'Water pollution', severity:'HIGH', status:'UNDER_REVIEW', location:'Msambazi River, Mzuzu', date:'Today, 08:16', reporter:'Peter Phiri', officer:'Martha Chirwa', description:'Discoloured water and a strong chemical smell reported near the footbridge.', lat:'-11.465', lon:'34.020', image:'https://images.unsplash.com/photo-1437482078695-73f5ca6c96e2?auto=format&fit=crop&w=900&q=80' },
  { id:'CEGCT-2025-0040', category:'Unsafe waste disposal', severity:'MEDIUM', status:'IN_PROGRESS', location:'Zomba Central Market', date:'Yesterday, 16:30', reporter:'Thoko Mbewe', officer:'James Nkhoma', description:'Waste is being burned behind the market after closing hours.', lat:'-15.385', lon:'35.318' },
  { id:'CEGCT-2025-0039', category:'Air pollution', severity:'HIGH', status:'IN_PROGRESS', location:'Chilomoni, Blantyre', date:'Yesterday, 13:05', reporter:'Chisomo Juma', officer:'Martha Chirwa', description:'Smoke from an industrial site is affecting nearby homes.', lat:'-15.786', lon:'35.002' },
  { id:'CEGCT-2025-0038', category:'Illegal dumping', severity:'LOW', status:'RESOLVED', location:'Kawale, Lilongwe', date:'Oct 04, 11:20', reporter:'Andrew Kalua', officer:'James Nkhoma', description:'Household refuse left along the roadside has now been cleared.', lat:'-13.954', lon:'33.777' },
];
const officers = ['Martha Chirwa', 'James Nkhoma', 'Ruth Moyo', 'Unassigned'];
const nav = [{id:'dashboard',label:'Overview',icon:'▦'},{id:'reports',label:'Reports queue',icon:'▤',badge:'12'},{id:'analytics',label:'Analytics',icon:'◷'},{id:'officers',label:'Officers',icon:'♙'}];
const statuses = ['SUBMITTED','UNDER_REVIEW','IN_PROGRESS','RESOLVED','REJECTED'];
const fmt = s => s.toLowerCase().replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());

function App(){
  const [page,setPage]=useState(window.location.pathname.replace('/','')||'dashboard');
  const [reports,setReports]=useState(initialReports);
  const [active,setActive]=useState(null);
  const [query,setQuery]=useState('');
  const [statusFilter,setStatusFilter]=useState('All status');
  const [categoryFilter,setCategoryFilter]=useState('All categories');
  const [toast,setToast]=useState('');
  const [mobileOpen,setMobileOpen]=useState(false);
  const [note,setNote]=useState('');
  const [messages,setMessages]=useState(['Hello Grace, we have received your report and our team is reviewing the location.']);
  const [message,setMessage]=useState('');
  const [login,setLogin]=useState(false);

  const notify = text => {setToast(text);window.setTimeout(()=>setToast(''),2600)};
  const changePage = p => {setPage(p);setActive(null);setMobileOpen(false);window.history.pushState({},'',p==='dashboard'?'/dashboard':`/${p}`)};
  const update = (id,changes) => setReports(prev=>prev.map(r=>r.id===id?{...r,...changes}:r));
  const filtered = useMemo(()=>reports.filter(r=>(statusFilter==='All status'||r.status===statusFilter)&&(categoryFilter==='All categories'||r.category===categoryFilter)&&`${r.id} ${r.location} ${r.description} ${r.category}`.toLowerCase().includes(query.toLowerCase())),[reports,statusFilter,categoryFilter,query]);
  if(login) return <div className="login-screen"><div className="login-card"><Brand/><div className="eyebrow">ADMINISTRATOR PORTAL</div><h1>Welcome back</h1><p>Sign in to manage community environmental reports.</p><label>Email address</label><input placeholder="you@cegct.org" type="email"/><label>Password</label><input placeholder="Enter your password" type="password"/><button className="primary full" onClick={()=>{setLogin(false);changePage('dashboard');notify('Demo mode: welcome to CEGCT')}}>Sign in <span>→</span></button><small>Supabase authentication will be connected when environment keys are configured.</small></div></div>;
  return <div className="app-shell">
    <aside className={`sidebar ${mobileOpen?'open':''}`}><div className="brand-wrap"><Brand/><button className="close-menu" onClick={()=>setMobileOpen(false)}>×</button></div><div className="workspace"><span className="workspace-icon">N</span><span><b>NEMA Malawi</b><small>Regional operations</small></span><span className="chev">⌄</span></div><div className="nav-label">WORKSPACE</div><nav>{nav.map(n=><button key={n.id} className={`nav-item ${page===n.id?'selected':''}`} onClick={()=>changePage(n.id)}><span className="nav-icon">{n.icon}</span>{n.label}{n.badge&&<span className="nav-badge">{n.badge}</span>}</button>)}</nav><div className="sidebar-bottom"><div className="help-card"><span className="help-icon">✳</span><b>Need a hand?</b><p>Visit the operations guide for help with your dashboard.</p><button onClick={()=>notify('Operations guide coming soon')}>Open guide <span>↗</span></button></div><button className="profile" onClick={()=>setLogin(true)}><span className="avatar">TK</span><span><b>Thoko Kalua</b><small>Administrator</small></span><span className="more">···</span></button></div></aside>
    <main className="main"><header className="topbar"><button className="hamburger" onClick={()=>setMobileOpen(true)}>☰</button><div className="crumb">Workspace <span>/</span> <b>{nav.find(n=>n.id===page)?.label||'Reports'}</b></div><div className="top-actions"><span className="live-indicator"><i/> Live updates</span><button className="icon-button" onClick={()=>notify('You’re all caught up')}>♧<i className="notification-dot"/></button><span className="top-divider"/><button className="top-user" onClick={()=>setLogin(true)}><span className="avatar small">TK</span><span>Thoko Kalua</span><span>⌄</span></button></div></header>
    <div className="content">
      {page==='dashboard'&&<Dashboard reports={reports} setActive={setActive} onQueue={()=>changePage('reports')}/>}
      {page==='reports'&&<Reports reports={filtered} all={reports} query={query} setQuery={setQuery} status={statusFilter} setStatus={setStatusFilter} category={categoryFilter} setCategory={setCategoryFilter} setActive={setActive} notify={notify}/>}
      {page==='analytics'&&<Analytics reports={reports}/>}
      {page==='officers'&&<Officers notify={notify}/>}
    </div>
    <footer><span>© 2025 CEGCT · Community Environmental Guardian & Cleanliness Tracker</span><span><i/> All systems operational</span></footer></main>
    {active&&<div className="overlay" onMouseDown={e=>e.target===e.currentTarget&&setActive(null)}><section className="detail-drawer"><div className="drawer-head"><div><span className="eyebrow">CASE FILE</span><h2>{active.id}</h2></div><button className="icon-button" onClick={()=>setActive(null)}>×</button></div><div className="drawer-scroll"><div className="detail-pills"><Severity value={active.severity}/><Status value={active.status}/></div><h3>{active.category}</h3><p className="detail-desc">{active.description}</p>{active.image&&<img className="evidence" src={active.image} alt="Report evidence"/>}<div className="detail-grid"><div><small>LOCATION</small><b>⌖ {active.location}</b></div><div><small>SUBMITTED</small><b>{active.date}</b></div><div><small>REPORTED BY</small><b>{active.reporter}</b></div><div><small>COORDINATES</small><b>{active.lat}, {active.lon}</b></div></div><label className="field-label">Case status</label><select value={active.status} onChange={e=>{update(active.id,{status:e.target.value});setActive({...active,status:e.target.value});notify('Case status updated')}}>{statuses.map(s=><option key={s}>{s}</option>)}</select><label className="field-label">Assigned officer</label><select value={active.officer} onChange={e=>{update(active.id,{officer:e.target.value});setActive({...active,officer:e.target.value});notify('Officer assignment updated')}}>{officers.map(o=><option key={o}>{o}</option>)}</select><div className="timeline-title"><h3>Case timeline</h3><span>Latest activity</span></div><div className="timeline"><div className="timeline-item"><i/><b>Report submitted</b><small>{active.date} · by {active.reporter}</small></div><div className="timeline-item"><i/><b>Case received by NEMA</b><small>Automated update · just now</small></div></div><label className="field-label">Add progress note</label><textarea value={note} onChange={e=>setNote(e.target.value)} placeholder="Share an update with the case record…"/><button className="primary full" onClick={()=>{if(note.trim()){notify('Progress note added to case timeline');setNote('')}}}>Post update <span>→</span></button><button className="secondary full chat-link" onClick={()=>{setActive({...active,chat:true})}}>◉ Open citizen chat</button>{active.chat&&<div className="chat-box"><b>Conversation with {active.reporter}</b>{messages.map((m,i)=><div className="chat-bubble" key={i}>{m}</div>)}<div className="chat-compose"><input value={message} onChange={e=>setMessage(e.target.value)} placeholder="Write a message…" onKeyDown={e=>e.key==='Enter'&&message.trim()&&(setMessages([...messages,message]),setMessage(''))}/><button onClick={()=>{if(message.trim()){setMessages([...messages,message]);setMessage('')}}}>➤</button></div></div>}</div></section></div>}
    {toast&&<div className="toast">✓ &nbsp;{toast}</div>}
  </div>
}
function Brand(){return <div className="brand"><div className="brand-mark"><span>✳</span></div><div><b>cegct</b><small>GUARDIANS OF OUR ENVIRONMENT</small></div></div>}
function Status({value}){return <span className={`status status-${value.toLowerCase()}`}><i/>{fmt(value)}</span>}
function Severity({value}){return <span className={`severity severity-${value.toLowerCase()}`}><i/>{fmt(value)}</span>}
function Dashboard({reports,setActive,onQueue}){
 const total=reports.length,pending=reports.filter(r=>['SUBMITTED','UNDER_REVIEW'].includes(r.status)).length,progress=reports.filter(r=>r.status==='IN_PROGRESS').length,resolved=reports.filter(r=>r.status==='RESOLVED').length;
 return <><div className="page-heading"><div><div className="eyebrow">WEDNESDAY, OCTOBER 7, 2026</div><h1>Good morning, Thoko <span>✳</span></h1><p>Here’s what’s happening across your region today.</p></div><button className="primary" onClick={onQueue}>View reports queue <span>→</span></button></div><div className="stat-grid"><Stat title="Total reports" value={total.toString().padStart(2,'0')} change="↑ 12%" note="vs. last month" icon="▤" tone="green"/><Stat title="Pending review" value={pending.toString().padStart(2,'0')} change="Needs attention" note="Review new cases" icon="◷" tone="amber"/><Stat title="In progress" value={progress.toString().padStart(2,'0')} change="Active cases" note="Across your region" icon="↗" tone="blue"/><Stat title="Resolved cases" value={resolved.toString().padStart(2,'0')} change="↑ 8%" note="vs. last month" icon="✓" tone="mint"/></div><div className="dashboard-grid"><section className="panel map-panel"><div className="panel-heading"><div><h2>Incident map</h2><p>Live environmental reports across Malawi</p></div><button className="select-like">This week⌄</button></div><div className="map"><div className="map-river"/><div className="map-road road-one"/><div className="map-road road-two"/><div className="map-label label-lilongwe">LILONGWE</div><div className="map-label label-mzuzu">MZUZU</div><div className="map-label label-zomba">ZOMBA</div><div className="map-label label-blantyre">BLANTYRE</div>{reports.filter(r=>r.status!=='RESOLVED').map((r,i)=><button key={r.id} title={r.id} onClick={()=>setActive(r)} className={`map-pin pin-${r.severity.toLowerCase()} pin-${i}`}><span/></button>)}<div className="map-credit">Map data © OpenStreetMap contributors</div><button className="map-expand">⛶</button></div><div className="map-legend"><span><i className="dot critical"/>Critical</span><span><i className="dot high"/>High</span><span><i className="dot medium"/>Medium</span><span><i className="dot low"/>Low</span><span className="map-count">{reports.filter(r=>r.status!=='RESOLVED').length} active reports</span></div></section><section className="panel feed-panel"><div className="panel-heading"><div><h2>Live report feed <span className="live-pill"><i/> LIVE</span></h2><p>Recent reports from citizens</p></div><button className="text-button" onClick={onQueue}>View all →</button></div><div className="feed-list">{reports.slice(0,4).map(r=><button className="feed-item" key={r.id} onClick={()=>setActive(r)}><div className={`feed-icon ${r.severity.toLowerCase()}`}>⌖</div><div className="feed-body"><div className="feed-top"><b>{r.category}</b><time>{r.date.split(',')[0]}</time></div><p>{r.location}</p><div className="feed-bottom"><span>{r.id}</span><Severity value={r.severity}/></div></div></button>)}</div><button className="feed-footer" onClick={onQueue}>Open reports queue <span>→</span></button></section></div><div className="bottom-grid"><section className="panel response-panel"><div className="panel-heading"><div><h2>Regional response</h2><p>Case resolution performance</p></div><span className="period">This month⌄</span></div><div className="response-content"><div className="ring"><div><b>78%</b><small>resolution rate</small></div></div><div className="response-stats"><div><span>Average response time</span><b>4.2 <small>hrs</small></b></div><div><span>Cases resolved</span><b>24 <small>of 31</small></b></div><div><span>Citizen satisfaction</span><b>4.8 <small>/ 5.0</small></b></div></div></div></section><section className="panel category-panel"><div className="panel-heading"><div><h2>Reports by category</h2><p>Distribution of submitted cases</p></div><button className="text-button" onClick={()=>{}}>This month⌄</button></div><div className="category-bars">{[['Illegal dumping',46,'#185835'],['Water pollution',30,'#4d9b78'],['Air pollution',17,'#e7aa45'],['Unsafe disposal',7,'#c8d9d3']].map(([label,n,color])=><div className="bar-row" key={label}><span>{label}</span><div className="bar-track"><i style={{width:`${n}%`,background:color}}/></div><b>{n}%</b></div>)}</div></section></div></>
}
function Stat({title,value,change,note,icon,tone}){return <section className="stat-card"><div className="stat-top"><span>{title}</span><i className={`stat-icon ${tone}`}>{icon}</i></div><div className="stat-number">{value}</div><div className="stat-note"><b className={tone}>{change}</b><span>{note}</span></div></section>}
function Reports({reports,all,query,setQuery,status,setStatus,category,setCategory,setActive,notify}){return <><div className="page-heading"><div><div className="eyebrow">CASE MANAGEMENT</div><h1>Reports queue</h1><p>Review, assign and track environmental cases.</p></div><button className="primary" onClick={()=>notify('Report export prepared')}>⇩ Export reports</button></div><div className="queue-summary"><div><b>{all.length}</b><span>Total reports</span></div><div><b>{all.filter(r=>r.status==='SUBMITTED').length}</b><span>Awaiting review</span></div><div><b>{all.filter(r=>r.status==='IN_PROGRESS').length}</b><span>In progress</span></div><div><b>{all.filter(r=>r.status==='RESOLVED').length}</b><span>Resolved</span></div></div><section className="panel table-panel"><div className="table-toolbar"><div className="search"><span>⌕</span><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search by case, location or keyword…"/></div><select value={status} onChange={e=>setStatus(e.target.value)}><option>All status</option>{statuses.map(s=><option key={s} value={s}>{fmt(s)}</option>)}</select><select value={category} onChange={e=>setCategory(e.target.value)}><option>All categories</option>{[...new Set(all.map(r=>r.category))].map(s=><option key={s}>{s}</option>)}</select><button className="filter-button" onClick={()=>{setStatus('All status');setCategory('All categories');setQuery('')}}>↺ Reset</button></div><div className="table-wrap"><table><thead><tr><th>CASE ID</th><th>CATEGORY</th><th>SEVERITY</th><th>STATUS</th><th>LOCATION</th><th>DATE REPORTED</th><th>ASSIGNED TO</th><th/></tr></thead><tbody>{reports.map(r=><tr key={r.id} onClick={()=>setActive(r)}><td><b className="case-id">{r.id}</b></td><td>{r.category}</td><td><Severity value={r.severity}/></td><td><Status value={r.status}/></td><td><span className="location-cell">⌖ {r.location}</span></td><td>{r.date}</td><td>{r.officer==='Unassigned'?<span className="unassigned">Unassigned</span>:r.officer}</td><td><button className="row-more" onClick={e=>{e.stopPropagation();setActive(r)}}>···</button></td></tr>)}</tbody></table>{reports.length===0&&<div className="empty">No reports match these filters.</div>}</div><div className="table-footer"><span>Showing <b>{reports.length?1:0}–{reports.length}</b> of <b>{reports.length}</b> reports</span><div><button disabled>← Previous</button><button className="page-active">1</button><button disabled>Next →</button></div></div></section></>}
function Analytics({reports}){return <><div className="page-heading"><div><div className="eyebrow">INSIGHTS & IMPACT</div><h1>Environmental analytics</h1><p>Track trends and measure your region’s impact.</p></div><button className="select-like">Last 30 days⌄</button></div><div className="stat-grid analytics-stats"><Stat title="Reports received" value="128" change="↑ 14.2%" note="vs. previous period" icon="▤" tone="green"/><Stat title="Resolution rate" value="78%" change="↑ 6.4%" note="vs. previous period" icon="✓" tone="mint"/><Stat title="Avg. response time" value="4.2h" change="↓ 18%" note="faster than last month" icon="◷" tone="blue"/><Stat title="Citizen reports" value="94%" change="↑ 3.1%" note="of total submissions" icon="♙" tone="amber"/></div><div className="analytics-grid"><section className="panel chart-panel"><div className="panel-heading"><div><h2>Reports by category</h2><p>Breakdown of environmental issues</p></div><span className="period">This month⌄</span></div><div className="hbar-chart">{[['Illegal dumping',48,'48','#185835'],['Water pollution',31,'31','#438a6a'],['Air pollution',24,'24','#84b9a0'],['Unsafe waste disposal',16,'16','#d5a84f'],['Other',9,'09','#becfc9']].map(x=><div className="hbar-row" key={x[0]}><span>{x[0]}</span><div><i style={{width:`${x[1]*1.7}%`,background:x[3]}}/></div><b>{x[2]}</b></div>)}</div></section><section className="panel chart-panel"><div className="panel-heading"><div><h2>Monthly resolution rate</h2><p>Cases resolved within each month</p></div><span className="period">2025⌄</span></div><div className="chart-legend"><span><i/> Resolution rate</span></div><div className="line-chart"><div className="y-labels"><span>100%</span><span>75%</span><span>50%</span><span>25%</span><span>0%</span></div><div className="chart-area"><div className="gridline g1"/><div className="gridline g2"/><div className="gridline g3"/><div className="gridline g4"/><svg viewBox="0 0 500 180" preserveAspectRatio="none"><path d="M0 130 C45 120 50 100 100 108 S165 85 200 98 S260 60 300 75 S360 64 400 57 S455 34 500 42" fill="none" stroke="#185835" strokeWidth="3"/><path d="M0 130 C45 120 50 100 100 108 S165 85 200 98 S260 60 300 75 S360 64 400 57 S455 34 500 42 L500 180 L0 180Z" fill="url(#fill)" opacity=".28"/><defs><linearGradient id="fill" x1="0" x2="0" y1="0" y2="1"><stop stopColor="#4c9473"/><stop offset="1" stopColor="#fff"/></linearGradient></defs></svg><div className="months"><span>May</span><span>Jun</span><span>Jul</span><span>Aug</span><span>Sep</span><span>Oct</span></div></div></div></section><section className="panel response-panel analytic-response"><div className="panel-heading"><div><h2>Response performance</h2><p>Average time to first officer action</p></div></div><div className="response-content"><div className="ring"><div><b>4.2h</b><small>average time</small></div></div><div className="response-stats"><div><span>Under 2 hours</span><b>38%</b></div><div><span>Under 8 hours</span><b>82%</b></div><div><span>Over 24 hours</span><b>6%</b></div></div></div></section></div></>}
function Officers({notify}){const data=[['MC','Martha Chirwa','Senior Environmental Officer','Lilongwe','8','5'],['JN','James Nkhoma','Environmental Officer','Blantyre','6','4'],['RM','Ruth Moyo','Field Response Officer','Mzuzu','5','3'],['PK','Peter Kachale','Environmental Officer','Zomba','4','2']];return <><div className="page-heading"><div><div className="eyebrow">TEAM MANAGEMENT</div><h1>Regional officers</h1><p>Manage your response team and active assignments.</p></div><button className="primary" onClick={()=>notify('Invite link copied')}>＋ Invite officer</button></div><div className="queue-summary"><div><b>12</b><span>Team members</span></div><div><b>8</b><span>Available now</span></div><div><b>23</b><span>Active assignments</span></div><div><b>4.8 <small>★</small></b><span>Average rating</span></div></div><section className="panel table-panel"><div className="panel-heading officer-heading"><div><h2>Officer directory</h2><p>Current regional response team</p></div><div className="search"><span>⌕</span><input placeholder="Search officers…"/></div></div><div className="officer-grid">{data.map((o,i)=><div className="officer-card" key={o[0]}><div className="officer-card-top"><span className={`avatar officer-avatar officer-${i}`}>{o[0]}</span><span className="available"><i/> Available</span><button className="row-more" onClick={()=>notify(`${o[1]} profile`)}>···</button></div><h3>{o[1]}</h3><p>{o[2]}</p><div className="officer-location">⌖ {o[3]} Regional Office</div><div className="officer-metrics"><span><b>{o[4]}</b> active cases</span><span><b>{o[5]}</b> resolved this month</span></div></div>)}</div></section></>}
export default App;
